public final class DefaultAccountBalancePresentationTransformer implements AccountBalancePresentationTransformer { @Override public PresentedAccountBalanceData transform(String language,ResolvedGeneralMetadataSet metadata){precisions(metadata);return new PresentedAccountBalanceData(Map.of(),Map.of());} public Map<GeneralMetadataName,BigInteger> precisions(ResolvedGeneralMetadataSet metadata){try{if(metadata==null)throw new IllegalArgumentException();var result=new EnumMap<GeneralMetadataName,BigInteger>(GeneralMetadataName.class);for(var name:GeneralMetadataName.values()){var key=new GeneralMetadataKey(name,GeneralMetadataType.PRECISION);String raw=metadata.find(key).orElseThrow().value();result.put(name,GeneralMetadataPrecision.parse(raw).value());}return Map.copyOf(result);}catch(RuntimeException ex){throw AccountBalanceRetrievalException.systemFailure();}} }
